  // Helper de traducción con interpolación posicional %1, %2, %3...
  function t(key, ...args) {
    const dict = I18N[currentLang] || I18N.es;
    let str = dict[key];
    if (str === undefined) str = (I18N.es[key] !== undefined) ? I18N.es[key] : key;
    args.forEach((arg, i) => {
      str = str.split(`%${i + 1}`).join(String(arg));
    });
    return str;
  }

